<section class="gamification-list"><header><h1><?php echo $this->lang('Awards') ?></h1></header><div class="gamification-grid"><?php foreach ($awards as $row): ?><article class="gamification-card gamification-award"><span class="gamification-rank">#<?php echo (int)$row['ranking'] ?></span><h2><a href="<?php echo url('awards/'.$row['award_id'].'/'.url_title($row['title'])) ?>"><?php echo utf8_htmlentities($row['title']) ?></a></h2><?php if ($row['team_title']): ?><strong><?php echo utf8_htmlentities($row['team_title']) ?></strong><?php endif ?><time><?php echo utf8_htmlentities($row['awarded_at']) ?></time></article><?php endforeach ?></div></section>
